import json, time, urllib.request, urllib.error
from datetime import datetime, timezone

BASE = "http://localhost:8080"
LOG = []

def req(method, path, token=None):
    headers = {"Authorization": f"Bearer {token}"} if token else {}
    r = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(r, timeout=30) as resp:
            return resp.status, dict(resp.headers), resp.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read().decode(errors="replace")
    except Exception as e:
        return None, {}, repr(e)

state = {"token": None}

def get_token():
    while True:
        st, h, body = req("POST", "/token")
        if st == 200:
            state["token"] = json.loads(body)["token"]
            return
        LOG.append(("token", st, body[:200]))
        time.sleep(wait_for(st, h, body))

def wait_for(st, h, body):
    ra = h.get("Retry-After")
    if ra:
        try:
            return float(ra) + 0.5
        except ValueError:
            pass
    try:
        j = json.loads(body)
        for k in ("retry_after", "retryAfter", "wait", "wait_seconds"):
            if k in j:
                return float(j[k]) + 0.5
    except Exception:
        pass
    return 2.0

def authed_get(path):
    attempts = 0
    while True:
        attempts += 1
        if state["token"] is None:
            get_token()
        st, h, body = req("GET", path, state["token"])
        if st == 200:
            return json.loads(body)
        LOG.append((path, st, body[:200]))
        if st == 401 or st == 403:
            state["token"] = None
            continue
        if st == 429 or st is None or st >= 500:
            time.sleep(wait_for(st, h, body))
            continue
        if st == 404:
            return None
        time.sleep(wait_for(st, h, body))

# 1. Orders, all pages
orders_raw = []
page = 1
total_pages = None
while True:
    data = authed_get(f"/orders?page={page}")
    total_pages = data["total_pages"]
    orders_raw.extend(data["items"])
    if page >= total_pages or data.get("next") is None:
        break
    page += 1

print("pages fetched:", page, "total_pages:", total_pages, "listings:", len(orders_raw))

# 2. Dedup by id
by_id = {}
dup_listings = 0
conflicts = 0
for o in orders_raw:
    if o["id"] in by_id:
        dup_listings += 1
        if by_id[o["id"]] != o:
            conflicts += 1
    else:
        by_id[o["id"]] = o
print("distinct ids:", len(by_id), "duplicate listings:", dup_listings, "conflicting dups:", conflicts)

# 3. Filter
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)
qual = []
status_counts = {}
for o in by_id.values():
    status_counts[o["status"]] = status_counts.get(o["status"], 0) + 1
    if o["status"] != "shipped":
        continue
    t = datetime.fromisoformat(o["placed_at"].replace("Z", "+00:00")).astimezone(timezone.utc)
    if START <= t < END:
        qual.append(o)
print("status counts:", status_counts)
print("qualifying orders:", len(qual))

# 4. Customers, cached
cust = {}
missing = set()
for cid in sorted({o["customer_id"] for o in qual}):
    c = authed_get(f"/customers/{cid}")
    if c is None:
        missing.add(cid)
    else:
        cust[cid] = c
print("customers looked up:", len(cust), "missing:", sorted(missing))

# 5. Discount per order, half-up rounding per order, integer math
by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
total = 0
for o in qual:
    c = cust.get(o["customer_id"])
    if c is None:
        raise SystemExit(f"no customer for {o['id']}")
    pct = c["discount_pct"]
    amt = o["amount_cents"]
    # round(amt * (100 - pct) / 100) half up, exact integers (amounts are non-negative)
    disc = (2 * amt * (100 - pct) + 100) // 200
    total += disc
    by_region[c["region"]] += disc

result = {
    "total_cents": total,
    "order_count": len(qual),
    "duplicates_skipped": dup_listings,
    "by_region": by_region,
}
print(json.dumps(result, indent=2))
print("sum regions:", sum(by_region.values()), "== total:", sum(by_region.values()) == total)
print("request issues logged:", len(LOG))
for l in LOG[:20]:
    print("  ", l)

with open("/workspace/result.json", "w") as f:
    json.dump(result, f, indent=2)
    f.write("\n")
EOF
cd /tmp/recon && python3 -I recon.py

